import { useTranslation } from "react-i18next";

import type { Brief } from "../../../../../model/types";
import type { RepoConfigContext } from "../../../../../model/utils/repo-config";
import type { BriefViewModel } from "../../../../../model/utils/view-model";
import { Provenance } from "../../Provenance";
import { CoverageLine } from "../CoverageLine";
import { FactBar } from "../FactBar";

export interface GeneratedBarProps {
  brief: Brief;
  model: BriefViewModel;
  repoConfig?: RepoConfigContext | null | undefined;
}

/** The card's Generated by section as a bar, for layouts with no card column. */
export function GeneratedBar({ brief, model, repoConfig }: GeneratedBarProps) {
  const { t } = useTranslation();

  return (
    <FactBar
      aside={<Provenance brief={brief} model={model} repoConfig={repoConfig} />}
      testId="generated-bar"
      title={t("brief.masthead.generatedBy")}
    >
      <CoverageLine brief={brief} />
    </FactBar>
  );
}
